settings.custom_liquid:
{%- assign p = all_products['4-week-band-strength-program'] -%}
{%- assign v = p.selected_or_first_available_variant -%}
{%- capture buy_url -%}{{ routes.root_url | append: '/' | replace: '//', '/' }}cart/{{ v.id }}:1{%- endcapture -%}
{%- capture price -%}{{ v.price | money_with_currency }}{%- endcapture -%}
<style>
.ms{--ink:#111315;--ink2:#1a1d21;--bone:#F3F0EA;--accent:#E8572A;--muted:#5d6168;--soft:#cfcac1;--line:#e2ddd3;color:var(--ink);font-family:var(--font-body--family),system-ui,sans-serif;overflow-x:clip}
.ms *{box-sizing:border-box}
.ms a{color:inherit}
.ms h1,.ms h2,.ms h3{font-family:var(--font-heading--family),system-ui,sans-serif;margin:0;line-height:1.04;letter-spacing:-.015em}
.ms-wrap{max-width:1140px;margin:0 auto;padding:0 20px}
.ms-eye{font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--accent);margin:0 0 14px}
.ms-btn{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 28px;border-radius:999px;font-weight:700;font-size:16px;text-decoration:none;transition:transform .2s ease,box-shadow .2s ease}
.ms-btn:hover{transform:translateY(-2px)}
.ms-main{background:var(--accent);color:#fff!important;box-shadow:0 12px 30px rgba(232,87,42,.35)}
.ms-main::after{content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.45),transparent);transform:skewX(-20deg);animation:ms-shine 3.6s ease-in-out infinite}
.ms-ghost{border:1.5px solid currentColor}
.ms-arrow{transition:transform .2s}.ms-btn:hover .ms-arrow{transform:translateX(4px)}
@keyframes ms-shine{0%,60%{left:-60%}100%{left:140%}}
/* progress */
.ms-progress{position:fixed;top:0;left:0;height:3px;width:100%;background:var(--accent);transform-origin:0 50%;transform:scaleX(0);z-index:60;pointer-events:none}
/* hero */
.ms-hero{position:relative;background:var(--ink);color:var(--bone);overflow:hidden;isolation:isolate}
.ms-glow{position:absolute;width:720px;height:720px;border-radius:50%;background:radial-gradient(circle,rgba(232,87,42,.32),transparent 62%);top:-260px;right:-180px;z-index:-1;animation:ms-drift 14s ease-in-out infinite alternate}
@keyframes ms-drift{to{transform:translate(-140px,120px) scale(1.15)}}
.ms-band{position:absolute;left:0;right:0;bottom:6px;height:90px;z-index:-1;opacity:.35}
.ms-band path{fill:none;stroke:var(--accent);stroke-width:3;stroke-linecap:round;animation:ms-stretch 4s cubic-bezier(.3,0,.2,1) infinite}
@keyframes ms-stretch{0%{d:path("M0 60 Q 600 60 1200 60")}25%{d:path("M0 60 Q 600 120 1200 60")}100%{d:path("M0 60 Q 600 60 1200 60")}}
.ms-hero .ms-wrap{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:center;padding-top:84px;padding-bottom:96px}
.ms-hero h1{font-size:clamp(44px,6.4vw,82px)}
.ms-hero h1 .ln{display:block;overflow:hidden;padding-bottom:.06em}
.ms-hero h1 .ln span{display:inline-block;transform:translateY(105%);animation:ms-rise .9s cubic-bezier(.2,.8,.2,1) forwards}
.ms-hero h1 .ln:nth-child(2) span{animation-delay:.12s;color:var(--accent)}
@keyframes ms-rise{to{transform:none}}
.ms-fade{opacity:0;animation:ms-fadeup .8s ease forwards}
@keyframes ms-fadeup{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
.ms-lead{font-size:18px;line-height:1.6;color:var(--soft);max-width:36ch;margin:22px 0 30px}
.ms-ctas{display:flex;flex-wrap:wrap;gap:12px}
.ms-trust{display:flex;flex-wrap:wrap;gap:8px 20px;margin:24px 0 0;padding:0;list-style:none;font-size:14px;color:var(--soft)}
.ms-trust li::before{content:"✓";color:var(--accent);font-weight:800;margin-right:6px}
.ms-art{position:relative;perspective:1000px}
.ms-art .float{animation:ms-float 6s ease-in-out infinite}
.ms-art img{display:block;width:100%;height:auto;border-radius:16px;transition:transform .25s ease-out;transform-style:preserve-3d;box-shadow:0 40px 90px rgba(0,0,0,.55)}
@keyframes ms-float{50%{transform:translateY(-12px)}}
.ms-stats{display:flex;gap:28px;margin-top:34px}
.ms-stats div{font-size:13px;color:var(--soft);line-height:1.3}
.ms-stats b{display:block;font-size:30px;color:var(--bone);font-family:var(--font-heading--family),sans-serif}
/* marquee */
.ms-marquee{background:var(--accent);color:#fff;overflow:hidden;white-space:nowrap;padding:16px 0;font-weight:800;letter-spacing:.14em;font-size:14px;text-transform:uppercase}
.ms-marquee div{display:inline-block;animation:ms-scroll 28s linear infinite}
.ms-marquee span{margin:0 22px}
.ms-marquee i{font-style:normal;opacity:.6}
@keyframes ms-scroll{to{transform:translateX(-50%)}}
/* sections */
.ms-sec{padding:88px 0}
.ms-sec h2{font-size:clamp(32px,4.4vw,52px);margin-bottom:14px}
.ms-sub{color:var(--muted);font-size:17px;line-height:1.6;max-width:58ch;margin:0 0 40px}
.ms-bone{background:var(--bone)}
.ms-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.ms-card{position:relative;background:#fff;border:1px solid var(--line);border-radius:18px;padding:30px;overflow:hidden;transition:transform .3s ease,box-shadow .3s ease}
.ms-card:hover{transform:translateY(-6px);box-shadow:0 22px 44px rgba(17,19,21,.1)}
.ms-card .n{font-size:64px;font-weight:900;line-height:1;color:transparent;-webkit-text-stroke:1.5px var(--accent);font-family:var(--font-heading--family),sans-serif}
.ms-card h3{font-size:22px;margin:16px 0 8px}
.ms-card p{margin:0;color:var(--muted);line-height:1.6;font-size:15px}
/* tempo demo */
.ms-tempo{background:var(--ink);color:var(--bone)}
.ms-tempo .ms-sub{color:var(--soft)}
.ms-rig{position:relative;height:150px;margin:10px 0 34px;border-radius:18px;background:var(--ink2);overflow:hidden}
.ms-door{position:absolute;left:28px;top:20px;bottom:20px;width:16px;border-radius:6px;background:#2d3137}
.ms-cord{position:absolute;left:44px;top:73px;height:4px;width:30%;border-radius:4px;background:var(--accent);transform-origin:0 50%;animation:ms-pull 4s cubic-bezier(.25,.1,.25,1) infinite}
.ms-handle{position:absolute;top:57px;left:calc(44px + 30%);width:20px;height:36px;border-radius:8px;border:4px solid var(--bone);animation:ms-handle 4s cubic-bezier(.25,.1,.25,1) infinite}
@keyframes ms-pull{0%{width:30%}25%{width:78%}100%{width:30%}}
@keyframes ms-handle{0%{left:calc(44px + 30%)}25%{left:calc(44px + 78%)}100%{left:calc(44px + 30%)}}
.ms-phases{display:grid;grid-template-columns:1fr 3fr;gap:12px}
.ms-ph{border-radius:14px;padding:18px 20px;background:var(--ink2);border:1px solid #2a2e33}
.ms-ph b{display:block;font-size:22px;letter-spacing:.06em}
.ms-ph span{color:var(--soft);font-size:14px}
.ms-ph.a{animation:ms-hiA 4s infinite}.ms-ph.b{animation:ms-hiB 4s infinite}
@keyframes ms-hiA{0%,24%{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}26%,100%{border-color:#2a2e33;box-shadow:none}}
@keyframes ms-hiB{0%,24%{border-color:#2a2e33;box-shadow:none}26%,98%{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}}
/* plan */
.ms-plan{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:48px;align-items:start}
.ms-tabs{display:inline-flex;background:var(--bone);border-radius:999px;padding:5px;margin-bottom:18px}
.ms-tabs button{border:0;background:transparent;font:inherit;font-weight:700;font-size:14px;padding:10px 18px;border-radius:999px;cursor:pointer;color:var(--muted);transition:background .2s,color .2s}
.ms-tabs button[aria-selected=true]{background:var(--ink);color:var(--bone)}
.ms-table{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#fff}
.ms-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:center;padding:15px 18px;border-top:1px solid var(--line);font-size:15px}
.ms-row:first-child{border-top:0}
.ms-row .i{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--ink);color:var(--bone);font-size:12px;font-weight:800}
.ms-row .s{font-weight:800;font-variant-numeric:tabular-nums}
.ms-panel[hidden]{display:none}
.ms-panel .ms-row{animation:ms-fadeup .45s ease both}
.ms-panel .ms-row:nth-child(2){animation-delay:.05s}.ms-panel .ms-row:nth-child(3){animation-delay:.1s}.ms-panel .ms-row:nth-child(4){animation-delay:.15s}.ms-panel .ms-row:nth-child(5){animation-delay:.2s}.ms-panel .ms-row:nth-child(6){animation-delay:.25s}
.ms-note{font-size:13px;color:var(--muted);margin:12px 2px 0}
.ms-pages{position:relative;height:520px}
.ms-pages img{position:absolute;width:62%;height:auto;border-radius:10px;box-shadow:0 26px 60px rgba(17,19,21,.22);background:#fff;transition:transform .5s cubic-bezier(.2,.8,.2,1)}
.ms-pages img:nth-child(1){left:0;top:30px;transform:rotate(-5deg)}
.ms-pages img:nth-child(2){right:0;top:0;transform:rotate(4deg)}
.ms-pages:hover img:nth-child(1){transform:rotate(-8deg) translate(-14px,10px)}
.ms-pages:hover img:nth-child(2){transform:rotate(7deg) translate(14px,-6px)}
.ms-list{list-style:none;padding:0;margin:26px 0 28px}
.ms-list li{display:flex;gap:12px;padding:10px 0;font-size:16px;line-height:1.5}
.ms-list li::before{content:"";flex:none;width:10px;height:10px;margin-top:8px;border-radius:50%;background:var(--accent)}
/* story */
.ms-story{position:relative;background:var(--ink);color:var(--bone);text-align:center;overflow:hidden}
.ms-story .ms-ar{font-size:clamp(110px,20vw,240px);max-width:none;line-height:1.35;font-weight:700;color:transparent;-webkit-text-stroke:1.5px rgba(232,87,42,.55);margin:-20px 0 4px;font-family:"Geeza Pro","Noto Naskh Arabic","Segoe UI","Arial",sans-serif}
.ms-story h2{font-size:clamp(30px,4vw,48px);max-width:18ch;margin:0 auto 18px}
.ms-story p{color:var(--soft);font-size:17px;line-height:1.7;max-width:56ch;margin:0 auto}
.ms-story p.ms-eye{font-size:12px;color:var(--accent);line-height:1.4;margin:0 auto 14px}
.ms-coach{display:inline-flex;align-items:center;gap:14px;margin-top:34px;padding:14px 22px;border:1px solid #2a2e33;border-radius:999px;text-align:left;font-size:14px;color:var(--soft)}
.ms-coach b{display:block;color:var(--bone);font-size:15px}
.ms-coach .badge{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:#fff;font-weight:900;font-size:13px}
/* faq */
.ms-faq{max-width:780px}
.ms-faq details{border-bottom:1px solid var(--line);padding:20px 0}
.ms-faq summary{cursor:pointer;font-weight:700;font-size:17px;list-style:none;display:flex;justify-content:space-between;gap:16px}
.ms-faq summary::-webkit-details-marker{display:none}
.ms-faq summary::after{content:"+";color:var(--accent);font-size:24px;line-height:1;transition:transform .3s}
.ms-faq details[open] summary::after{transform:rotate(45deg)}
.ms-faq p{margin:12px 0 0;color:var(--muted);line-height:1.65;animation:ms-fadeup .35s ease}
/* final */
.ms-final{text-align:center;background:radial-gradient(circle at 50% 120%,rgba(232,87,42,.22),transparent 60%),var(--bone)}
.ms-final h2{font-size:clamp(36px,5.4vw,64px)}
.ms-fine{font-size:13px;color:var(--muted);text-align:center;margin:0;padding:22px 20px 40px;background:var(--bone)}
/* sticky bar */
.ms-sticky{position:fixed;left:12px;right:12px;bottom:12px;z-index:55;display:none;align-items:center;justify-content:space-between;gap:12px;padding:10px 10px 10px 18px;border-radius:999px;background:rgba(17,19,21,.94);color:var(--bone);box-shadow:0 18px 40px rgba(0,0,0,.35);transform:translateY(140%);transition:transform .35s cubic-bezier(.2,.8,.2,1);backdrop-filter:blur(8px)}
.ms-sticky.on{transform:none}
.ms-sticky b{font-size:14px;display:block}.ms-sticky span{font-size:12px;color:var(--soft)}
.ms-sticky .ms-btn{min-height:44px;padding:0 20px;font-size:14px}
/* reveal */
.ms-r{opacity:0;transform:translateY(34px);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.8,.2,1)}
.ms-r.in{opacity:1;transform:none}
.ms-d1{transition-delay:.1s}.ms-d2{transition-delay:.2s}.ms-d3{transition-delay:.3s}
@media (max-width:849px){
  .ms-hero .ms-wrap,.ms-plan{grid-template-columns:minmax(0,1fr);gap:36px}
  .ms-hero .ms-wrap{padding-top:48px;padding-bottom:72px}
  .ms-cards{grid-template-columns:minmax(0,1fr)}
  .ms-sec{padding:64px 0}
  .ms-ctas .ms-btn{width:100%}
  .ms-pages{height:360px}
  .ms-phases{grid-template-columns:1fr 1.6fr}
  .ms-sticky{display:flex}
  .ms-stats{gap:20px}
}
@media (prefers-reduced-motion:reduce){
  .ms *,.ms *::before,.ms *::after{animation:none!important;transition:none!important}
  .ms-hero h1 .ln span{transform:none}.ms-fade{opacity:1}.ms-r{opacity:1;transform:none}
}
</style>

<div class="ms" id="ms">
  <div class="ms-progress" id="ms-progress"></div>

  <section class="ms-hero">
    <div class="ms-glow"></div>
    <svg class="ms-band" viewBox="0 0 1200 120" preserveAspectRatio="none" aria-hidden="true"><path d="M0 60 Q 600 60 1200 60"/></svg>
    <div class="ms-wrap">
      <div>
        <p class="ms-eye ms-fade" style="animation-delay:.05s">Masir · مصير</p>
        <h1><span class="ln"><span>Home strength,</span></span><span class="ln"><span>coached.</span></span></h1>
        <p class="ms-lead ms-fade" style="animation-delay:.35s">A real 4-week plan for a resistance band and a door. Three 30-minute sessions a week, written by a certified strength coach.</p>
        <div class="ms-ctas ms-fade" style="animation-delay:.5s">
          <a class="ms-btn ms-main" href="{{ buy_url }}">Get the program · {{ price }} <span class="ms-arrow">→</span></a>
          <a class="ms-btn ms-ghost" href="#ms-plan">See the plan</a>
        </div>
        <ul class="ms-trust ms-fade" style="animation-delay:.65s"><li>Instant PDF download</li><li>30-day money-back guarantee</li></ul>
        <div class="ms-stats ms-fade" style="animation-delay:.8s">
          <div><b data-count="4">4</b>weeks</div><div><b data-count="3">3</b>sessions a week</div><div><b data-count="30">30</b>minutes each</div>
        </div>
      </div>
      <div class="ms-art ms-fade" style="animation-delay:.25s">
        <div class="float">
          {%- if p.featured_image -%}
            {{ p.featured_image | image_url: width: 1400 | image_tag: loading: 'eager', fetchpriority: 'high', id: 'ms-tilt', alt: 'The 4-Week Band Strength Program by Masir, cover and pages', sizes: '(min-width: 850px) 50vw, 100vw' }}
          {%- endif -%}
        </div>
      </div>
    </div>
  </section>

  <div class="ms-marquee" aria-hidden="true"><div>{%- for i in (1..2) -%}<span>One band</span><i>✦</i><span>One door</span><i>✦</i><span>30 minutes</span><i>✦</i><span>3× a week</span><i>✦</i><span>Coached, not random</span><i>✦</i><span>Instant download</span><i>✦</i>{%- endfor -%}</div></div>

  <section class="ms-sec ms-bone">
    <div class="ms-wrap">
      <p class="ms-eye ms-r">How it works</p>
      <h2 class="ms-r ms-d1">A plan, not a playlist.</h2>
      <p class="ms-sub ms-r ms-d2">Most band workouts are a random list of exercises. This one tells you what to do each day, how hard, and how to make it harder.</p>
      <div class="ms-cards">
        <div class="ms-card ms-r"><div class="n">01</div><h3>Learn the moves</h3><p>Weeks 1-2 teach the squat, hinge, press, pull and core patterns with a light band.</p></div>
        <div class="ms-card ms-r ms-d1"><div class="n">02</div><h3>Add load</h3><p>Weeks 3-4 move you up a band and add sets, so you keep getting stronger instead of just tired.</p></div>
        <div class="ms-card ms-r ms-d2"><div class="n">03</div><h3>Prove it</h3><p>Test two lifts on day 1 and again in week 4, and log your band and reps every week.</p></div>
      </div>
    </div>
  </section>

  <section class="ms-sec ms-tempo">
    <div class="ms-wrap">
      <p class="ms-eye ms-r">The one rule</p>
      <h2 class="ms-r ms-d1">The slow way back is the workout.</h2>
      <p class="ms-sub ms-r ms-d2">Bands are easy to do badly: people rush the rep and let the band snap back. Every exercise in the plan uses one tempo.</p>
      <div class="ms-rig ms-r" aria-hidden="true"><div class="ms-door"></div><div class="ms-cord"></div><div class="ms-handle"></div></div>
      <div class="ms-phases ms-r ms-d1"><div class="ms-ph a"><b>PULL</b><span>1 second</span></div><div class="ms-ph b"><b>RETURN</b><span>2-3 seconds, under control</span></div></div>
    </div>
  </section>

  <section class="ms-sec" id="ms-plan">
    <div class="ms-wrap ms-plan">
      <div>
        <p class="ms-eye ms-r">Inside the plan</p>
        <h2 class="ms-r ms-d1">Here's Day A.</h2>
        <p class="ms-sub ms-r ms-d2" style="margin-bottom:24px">The full program has Day A and Day B, a 5-minute warm-up, coaching cues for every exercise, a safety check and your progress log.</p>
        <div class="ms-r ms-d2">
          <div class="ms-tabs" role="tablist">
            <button role="tab" aria-selected="true" data-tab="w12">Weeks 1-2</button>
            <button role="tab" aria-selected="false" data-tab="w34">Weeks 3-4</button>
          </div>
          <div class="ms-panel" data-panel="w12"><div class="ms-table">
            <div class="ms-row"><span class="i">1</span><span>Banded squat</span><span class="s">3 × 12</span></div>
            <div class="ms-row"><span class="i">2</span><span>Door-anchored chest press</span><span class="s">3 × 12</span></div>
            <div class="ms-row"><span class="i">3</span><span>Standing row</span><span class="s">3 × 12</span></div>
            <div class="ms-row"><span class="i">4</span><span>Banded glute bridge</span><span class="s">3 × 15</span></div>
            <div class="ms-row"><span class="i">5</span><span>Pallof press</span><span class="s">2 × 10 / side</span></div>
          </div></div>
          <div class="ms-panel" data-panel="w34" hidden><div class="ms-table">
            <div class="ms-row"><span class="i">1</span><span>Banded squat</span><span class="s">4 × 10</span></div>
            <div class="ms-row"><span class="i">2</span><span>Door-anchored chest press</span><span class="s">4 × 10</span></div>
            <div class="ms-row"><span class="i">3</span><span>Standing row</span><span class="s">4 × 10</span></div>
            <div class="ms-row"><span class="i">4</span><span>Banded glute bridge</span><span class="s">3 × 15</span></div>
            <div class="ms-row"><span class="i">5</span><span>Pallof press</span><span class="s">3 × 10 / side</span></div>
            <div class="ms-row"><span class="i">+</span><span>Finisher: pull-aparts, good mornings, plank</span><span class="s">3 rounds</span></div>
          </div></div>
          <p class="ms-note">Weeks 3-4: move up a band, or step farther from the anchor, on the main lifts.</p>
        </div>
      </div>
      <div>
        <div class="ms-pages ms-r ms-d1">
          {%- if p.images[1] -%}{{ p.images[1] | image_url: width: 800 | image_tag: loading: 'lazy', alt: 'Coaching cues page' }}{%- endif -%}
          {%- if p.images[2] -%}{{ p.images[2] | image_url: width: 800 | image_tag: loading: 'lazy', alt: 'Progress log page' }}{%- endif -%}
        </div>
        <ul class="ms-list ms-r ms-d2">
          <li>6-page PDF: prints well and reads well on a phone</li>
          <li>You need a tube-band set with handles, a door anchor and ankle straps, and a door that closes</li>
          <li>Built for beginners: weeks 1-2 start light</li>
        </ul>
        <a class="ms-btn ms-main ms-r ms-d3" href="{{ buy_url }}">Get the program · {{ price }} <span class="ms-arrow">→</span></a>
      </div>
    </div>
  </section>

  <section class="ms-sec ms-story">
    <div class="ms-wrap">
      <p class="ms-ar ms-r" lang="ar">مصير</p>
      <p class="ms-eye ms-r ms-d1">Masir: Arabic for destiny</p>
      <h2 class="ms-r ms-d1">Your strength isn't luck. It's built.</h2>
      <p class="ms-r ms-d2">Rep by rep, week by week. Masir writes plans the way a coach trains a client: learn the movement, own it, then make it harder.</p>
      <div class="ms-coach ms-r ms-d3"><span class="badge">CPT</span><span><b>Hussein Dar Abu Hussein</b>ISSA Certified Personal Trainer · Strength &amp; Conditioning Specialist · Ottawa</span></div>
    </div>
  </section>

  <section class="ms-sec ms-bone">
    <div class="ms-wrap ms-faq">
      <p class="ms-eye ms-r">Questions</p>
      <h2 class="ms-r ms-d1">Before you start</h2>
      <details open><summary>What bands do I need?</summary><p>Any tube-band set with handles, a door anchor and ankle straps. If you can attach a band to a door and hold both handles, you're set.</p></details>
