    art.addEventListener('mousemove',function(e){var b=art.getBoundingClientRect();var x=(e.clientX-b.left)/b.width-.5,y=(e.clientY-b.top)/b.height-.5;img.style.transform='rotateY('+(x*10)+'deg) rotateX('+(-y*10)+'deg)';});
    art.addEventListener('mouseleave',function(){img.style.transform='';});
  }
  if(!reduce){root.querySelectorAll('[data-count]').forEach(function(el){var n=+el.getAttribute('data-count'),s=null;el.textContent='0';function step(ts){if(!s)s=ts;var p=Math.min((ts-s)/1200,1);el.textContent=Math.round(n*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(step);}setTimeout(function(){requestAnimationFrame(step)},900);});}
})();
</script>
